`define BRAM_AUTO
module al_axi_clock_converter #

  (
   parameter		 AXI_PROTOCOL	= 0,					    
   parameter 		 AXI_ID_WIDTH	= 8,                          
   parameter 		 AXI_ADDR_WIDTH = 32,                  
   parameter 		 AXI_DATA_WIDTH = 64,                  
   parameter 		 US_ACLK_RATIO	= 4,                    
   parameter 		 DS_ACLK_RATIO	= 1,					   
             		                                       
   parameter 		 IS_ACLK_ASYNC	= 0,                    

   parameter		 AW_FIFO_DEPTH	= 32,						
   parameter		 AR_FIFO_DEPTH	= 32,						
   parameter		 W_FIFO_DEPTH	= 32,						
   parameter		 R_FIFO_DEPTH	= 32,						
   parameter		 B_FIFO_DEPTH	= 32,						

   parameter		 AXI_SUPPORTS_USER_SIGNALS  = 1,         
   parameter 		 AWUSER_WIDTH	= 1,                      
   parameter 		 ARUSER_WIDTH	= 1,                
   parameter 		 WUSER_WIDTH	= 1,                 
   parameter 		 RUSER_WIDTH	= 1,                 
   parameter 		 BUSER_WIDTH	= 1,                   
   parameter 		 SUPPORTS_WRITE_CHANNEL = 1,            
   parameter 		 SUPPORTS_READ_CHANNEL	= 1                

  )
  (
//us: upper stream      ds: down stream
   input  wire										us_aclk,
   input  wire										us_aresetn,
   input  wire [AXI_ID_WIDTH-1:0]					us_awid,
   input  wire [AXI_ADDR_WIDTH-1:0]                 us_awaddr,
   input  wire [((AXI_PROTOCOL == 1) ? 4 : 8)-1:0]  us_awlen,
   input  wire [2:0]                                us_awsize,
   input  wire [1:0]                                us_awburst,
   input  wire [((AXI_PROTOCOL == 1) ? 2 : 1)-1:0]  us_awlock,
   input  wire [3:0]								us_awcache,
   input  wire [2:0]								us_awprot,
   input  wire [3:0]								us_awregion,
   input  wire [3:0]								us_awqos,
   input  wire [AWUSER_WIDTH-1:0]					us_awuser,
   input  wire										us_awvalid,
   output reg										us_awready,

   input  wire [AXI_ID_WIDTH-1:0]					us_wid,
   input  wire [AXI_DATA_WIDTH-1:0]					us_wdata,
   input  wire [AXI_DATA_WIDTH/8-1:0]				us_wstrb,
   input  wire										us_wlast,
   input  wire [WUSER_WIDTH-1:0]					us_wuser,
   input  wire										us_wvalid,
   output reg										us_wready,

   output reg [AXI_ID_WIDTH-1:0]					us_bid,
   output reg [1:0]									us_bresp,
   output reg [BUSER_WIDTH-1:0]						us_buser,
   output reg										us_bvalid,
   input  wire										us_bready,

   input  wire [AXI_ID_WIDTH-1:0]					us_arid,
   input  wire [AXI_ADDR_WIDTH-1:0]					us_araddr,
   input  wire [((AXI_PROTOCOL == 1) ? 4 : 8)-1:0]  us_arlen,
   input  wire [2:0]								us_arsize,
   input  wire [1:0]								us_arburst,
   input  wire [((AXI_PROTOCOL == 1) ? 2 : 1)-1:0]	us_arlock,
   input  wire [3:0]								us_arcache,
   input  wire [2:0]								us_arprot,
   input  wire [3:0]								us_arregion,
   input  wire [3:0]								us_arqos,
   input  wire [ARUSER_WIDTH-1:0]					us_aruser,
   input  wire										us_arvalid,
   output reg										us_arready,

   output reg [AXI_ID_WIDTH-1:0]					us_rid,
   output reg [AXI_DATA_WIDTH-1:0]					us_rdata,
   output reg [1:0]									us_rresp,
   output reg										us_rlast,
   output reg [RUSER_WIDTH-1:0]						us_ruser,
   output reg										us_rvalid,
   input  wire										us_rready,

   input  wire										ds_aclk,
   input  wire										ds_aresetn,

   output reg [AXI_ID_WIDTH-1:0]					ds_awid,
   output reg [AXI_ADDR_WIDTH-1:0]					ds_awaddr,
   output reg [((AXI_PROTOCOL == 1) ? 4 : 8)-1:0]	ds_awlen,
   output reg [2:0]									ds_awsize,
   output reg [1:0]									ds_awburst,
   output reg [((AXI_PROTOCOL == 1) ? 2 : 1)-1:0]	ds_awlock,
   output reg [3:0]									ds_awcache,
   output reg [2:0]									ds_awprot,
   output reg [3:0]									ds_awregion,
   output reg [3:0]									ds_awqos,
   output reg [AWUSER_WIDTH-1:0]					ds_awuser,
   output reg										ds_awvalid,
   input  wire										ds_awready,

   output reg [AXI_ID_WIDTH-1:0]					ds_wid,
   output reg [AXI_DATA_WIDTH-1:0]					ds_wdata,
   output reg [AXI_DATA_WIDTH/8-1:0]				ds_wstrb,
   output reg										ds_wlast,
   output reg [WUSER_WIDTH-1:0]						ds_wuser,
   output reg										ds_wvalid,
   input  wire										ds_wready,

   input  wire [AXI_ID_WIDTH-1:0]					ds_bid,
   input  wire [1:0]								ds_bresp,
   input  wire [BUSER_WIDTH-1:0]					ds_buser,
   input  wire										ds_bvalid,
   output reg										ds_bready,

   output reg [AXI_ID_WIDTH-1:0]					ds_arid,
   output reg [AXI_ADDR_WIDTH-1:0]					ds_araddr,
   output reg [((AXI_PROTOCOL == 1) ? 4 : 8)-1:0]	ds_arlen,
   output reg [2:0]									ds_arsize,
   output reg [1:0]									ds_arburst,
   output reg [((AXI_PROTOCOL == 1) ? 2 : 1)-1:0]	ds_arlock,
   output reg [3:0]									ds_arcache,
   output reg [2:0]									ds_arprot,
   output reg [3:0]									ds_arregion,
   output reg [3:0]									ds_arqos,
   output reg [ARUSER_WIDTH-1:0]					ds_aruser,
   output reg										ds_arvalid,
   input  wire										ds_arready,

   input  wire [AXI_ID_WIDTH-1:0]					ds_rid,
   input  wire [AXI_DATA_WIDTH-1:0]					ds_rdata,
   input  wire [1:0]								ds_rresp,
   input  wire										ds_rlast,
   input  wire [RUSER_WIDTH-1:0]					ds_ruser,
   input  wire										ds_rvalid,
   output reg										ds_rready);

